  --query 'knowledgeBase.status' --output text)" = "ACTIVE" ]; do sleep 5; done
MANAGED_DS_ID=$(aws bedrock-agent list-data-sources --knowledge-base-id "${MANAGED_KB_ID}" --no-cli-pager \
  --query 'dataSourceSummaries[0].dataSourceId' --output text)
if [ "${MANAGED_DS_ID}" = "None" ]; then
