      "connectorParameters": {"type": "S3", "version": "1",
        "connectionConfiguration": {"bucketName": "'${DATA_BUCKET}'", "bucketOwnerAccountId": "'${ACCOUNT_ID}'"},
        "filterConfiguration": {"inclusionPrefixes": ["policies/"]}}}}' \
    --no-cli-pager --query 'dataSource.dataSourceId' --output text)
fi
until [ "$(aws bedrock-agent get-data-source --knowledge-base-id "${MANAGED_KB_ID}" --data-source-id "${MANAGED_DS_ID}" \
