  --no-cli-pager --query 'ingestionJob.ingestionJobId' --output text)
until [ "$(aws bedrock-agent get-ingestion-job --knowledge-base-id "${MANAGED_KB_ID}" --data-source-id "${MANAGED_DS_ID}" \
  --ingestion-job-id "${JOB_ID}" --no-cli-pager --query 'ingestionJob.status' --output text)" = "COMPLETE" ]; do
