        model,
        tools=tools,
        middleware=[memory.with_long_term_memory(SYSTEM_PROMPT), memory.save_turn],
        context_schema=memory.Context,
        checkpointer=memory.checkpointer,
        store=memory.store,
    )


_agent = None


async def get_agent():
    global _agent
    if _agent is None:
        _agent = build_agent(TOOLS + await gateway_tools())
