  "{\"userId\": \"alice\", \"amount\": 4200, \"currency\": \"EUR\", \"date\": \"${TRIP_START}\", \"description\": \"Business class flight Berlin-San Francisco\", \"type\": \"FLIGHT\"}"
WS_TEST_BLOCK_1610_7

